; Generated by tools/build_audio.py; fixed-bank callback for this Super FX ROM.
.setcpu "65816"
.smart
.export LoadAudioData: far
.export Tad_Loader_Bin := audio_data
.export Tad_Loader_SIZE = 116
.export Tad_AudioDriver_Bin := audio_data + 116
.export Tad_AudioDriver_SIZE = 3221
.import TAD_IO_VERSION
.assert TAD_IO_VERSION = 20, lderror, "TAD IO version mismatch"
.segment "BOOT"
.a8
.i16
LoadAudioData:
  cmp #0
  beq common
  cmp #1
  beq song
  clc
  rtl
common:
  lda #.bankbyte(audio_data + 3345)
  ldx #.loword(audio_data + 3345)
