  sec
  rtl
song:
  lda #.bankbyte(audio_data + 45087)
  ldx #.loword(audio_data + 45087)
  ldy #8305
  sec
  rtl
.segment "AUDIO59"
audio_data: .incbin "data.bin"
.assert .bankbyte(audio_data) = .bankbyte(audio_data + 53392 - 1), lderror, "Audio data crosses bank"
